@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({
        "status": "ok",
        "model": research_engine.model_id,
        "max_tokens": research_engine.max_tokens
    })

@app.route('/api/research', methods=['POST'])
def research():
    try:
        data = request.json
        query = data.get('query', '')

        if not query:
            return jsonify({"error": "Query parameter is required"}), 400

        analysis = research_engine.analyze_query(query)

        queries = research_engine.generate_queries(query, analysis)

        search_results = research_engine.search_exa(queries, analysis)

        ranked_results = research_engine.rank_results(search_results, top_n=300)

        context = research_engine.build_context(ranked_results)

        if len(context) > 1500000:
            context = context[:1500000]

        answer = research_engine.generate_answer(query, context, analysis)

        return jsonify({
            "query": query,
            "answer": answer,
            "analysis": analysis,
            "sources_count": len(ranked_results),
            "queries_used": len(queries)
        })

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/research/stream', methods=['POST'])
def research_stream():
    try:
        data = request.json
        query = data.get('query', '')

        if not query:
            return jsonify({"error": "Query parameter is required"}), 400

        def generate():
            try:
                yield f"data: {json.dumps({'type': 'status', 'message': 'Analyzing query...'})}\n\n"

                analysis = research_engine.analyze_query(query)
                yield f"data: {json.dumps({'type': 'analysis', 'data': analysis})}\n\n"

                yield f"data: {json.dumps({'type': 'status', 'message': 'Generating search queries...'})}\n\n"
                queries = research_engine.generate_queries(query, analysis)
                yield f"data: {json.dumps({'type': 'queries', 'count': len(queries)})}\n\n"

                yield f"data: {json.dumps({'type': 'status', 'message': 'Searching Exa AI...'})}\n\n"
                search_results = research_engine.search_exa(queries, analysis)
                yield f"data: {json.dumps({'type': 'search_results', 'count': len(search_results)})}\n\n"

                yield f"data: {json.dumps({'type': 'status', 'message': 'Ranking results...'})}\n\n"
                ranked_results = research_engine.rank_results(search_results, top_n=300)
                yield f"data: {json.dumps({'type': 'ranked_results', 'count': len(ranked_results)})}\n\n"

                yield f"data: {json.dumps({'type': 'status', 'message': 'Building context...'})}\n\n"
                context = research_engine.build_context(ranked_results)

                if len(context) > 1500000:
                    context = context[:1500000]

                yield f"data: {json.dumps({'type': 'status', 'message': 'Generating answer...'})}\n\n"

                for chunk in research_engine.generate_answer_stream(query, context, analysis):
                    yield f"data: {json.dumps({'type': 'answer_chunk', 'content': chunk})}\n\n"

                yield f"data: {json.dumps({'type': 'done'})}\n\n"

            except Exception as e:
                yield f"data: {json.dumps({'type': 'error', 'message': str(e)})}\n\n"

        return Response(generate(), mimetype='text/event-stream')

    except Exception as e:
        return jsonify({"error": str(e)}), 500

